'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='rotoformas-almacen-moldes-v1';let state=Model.empty(),page='Inicio',query='',saveBlocked=false;
try{const saved=localStorage.getItem(KEY);if(saved)state=Model.validate(JSON.parse(saved));}catch(e){saveBlocked=true;alert('No se han podido cargar los datos guardados. No se sobrescribirán. Conserva una copia del almacenamiento y revisa el problema antes de continuar.');}
const pages=['Inicio','Moldes','Ubicaciones','Movimientos','Etiquetas','Catálogos','Copias y ayuda'];
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)}
function persist(next){if(saveBlocked)throw Error('El almacenamiento está bloqueado para proteger los datos anteriores.');Model.validate(next);try{localStorage.setItem(KEY,JSON.stringify(next));}catch(e){throw Error('No se pudo guardar. Comprueba el espacio disponible y exporta una copia.');}state=next;render();}
function mutate(fn){const next=structuredClone(state);fn(next);persist(next)}
function label(text,name,type='text',value='',extra=''){return `<label for="f-${name}">${text}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}
function select(text,name,options,value='',required=true){return `<label for="f-${name}">${text}</label><select id="f-${name}" name="${name}" ${required?'required':''}><option value="">Seleccionar…</option>${options.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`}
const notes=(v='')=>`<label for="f-notes">Observaciones (opcional)</label><textarea id="f-notes" name="notes" maxlength="2000">${esc(v)}</textarea>`;
function modal(title,html,fn){$('form-title').textContent=title;$('fields').innerHTML=html;$('error').textContent='';$('form').onsubmit=e=>{e.preventDefault();try{fn(Object.fromEntries(new FormData(e.target)));$('modal').close();toast('Guardado correctamente');}catch(err){$('error').textContent=err.message}};$('modal').showModal()}
$('close').onclick=$('cancel').onclick=()=>$('modal').close();
function ownerName(m){return state.owners.find(o=>o.id===m.owner)?.name||''}function typeName(m){return state.types.find(t=>t.id===m.type)?.name||''}
function empty(title,body,button='',action=''){return `<div class="empty"><div class="eyebrow">LISTO PARA EMPEZAR</div><h3>${title}</h3><p>${body}</p>${button?`<button class="primary" data-action="${action}">${button}</button>`:''}</div>`}
function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function cat(kind){const title=kind==='owners'?'propietario':'tipo de molde';modal('Añadir '+title,label('Nombre','name','text','','required maxlength="100"')+label('Abreviatura','abbr','text','','required pattern="[A-Za-z0-9]{2,8}" minlength="2" maxlength="8"')+'<p class="hint">Entre 2 y 8 letras o números. Se guardará en mayúsculas y formará parte del código del molde.</p>',v=>mutate(s=>{v.name=v.name.trim();v.abbr=v.abbr.toUpperCase();if(!v.name)throw Error('Indica un nombre.');if(s[kind].some(x=>x.abbr===v.abbr||x.name.toLowerCase()===v.name.toLowerCase()))throw Error('Ese nombre o abreviatura ya existe.');s[kind].push({id:Model.uid(),...v})}))}
function newLocations(){modal('Crear ubicaciones',`<p class="hint">Una estantería es una fila completa. Los módulos se numeran a lo largo de ella; los niveles, desde abajo.</p>`+label('Número de estantería','e','number','1','required min="1" max="999" step="1"')+`<div class="row">${label('Primer módulo','start','number','1','required min="1" max="999" step="1"')}${label('Número de módulos','count','number','1','required min="1" max="100" step="1"')}</div>`+label('Niveles por módulo','levels','number','1','required min="1" max="30" step="1"')+'<p class="hint">Se crearán códigos como E1M1N1. Las ubicaciones que ya existen se conservarán.</p>',v=>mutate(s=>{let count=0;const e=+v.e,start=+v.start,modules=+v.count,levels=+v.levels;if(start+modules-1>999||modules*levels>1000)throw Error('Crea como máximo 1.000 ubicaciones por operación y módulos hasta el 999.');for(let m=start;m<start+modules;m++)for(let n=1;n<=levels;n++){const code=Model.locCode(e,m,n);if(!s.locations.some(l=>l.code===code)){s.locations.push({id:Model.uid(),code,e,m,n});count++}}if(!count)throw Error('Estas ubicaciones ya existen.');s.locations.sort((a,b)=>a.e-b.e||a.m-b.m||a.n-b.n)}))}
function moldForm(id){const m=state.molds.find(m=>m.id===id);if(!m&&(!state.owners.length||!state.types.length)){page='Catálogos';render();toast('Añade primero un propietario y un tipo de molde.');return;}
 const html=(m?`<p class="code">${esc(m.code)}</p><p class="hint">Propietario: ${esc(ownerName(m))} · Tipo: ${esc(typeName(m))}. El código se conserva durante la vida del molde.</p>`:select('Propietario','owner',state.owners)+select('Tipo de molde','type',state.types)+'<p class="hint">Se asignará automáticamente un código único: propietario-tipo-número.</p>')+label('Nombre o referencia del producto (opcional)','name','text',m?.name,'maxlength="150"')+'<details><summary>Parámetros técnicos opcionales</summary>'+`<div class="row">${label('Largo (mm)','length','number',m?.length,'min="0" step="any"')}${label('Ancho (mm)','width','number',m?.width,'min="0" step="any"')}${label('Alto (mm)','height','number',m?.height,'min="0" step="any"')}${label('Peso (kg)','weight','number',m?.weight,'min="0" step="any"')}</div>`+label('Material del molde','material','text',m?.material,'maxlength="100"')+label('Número de piezas','pieces','number',m?.pieces,'min="1" step="1"')+'</details>'+notes(m?.notes);
 modal(m?'Ficha del molde':'Registrar molde',html,v=>mutate(s=>{if(m){Object.assign(s.molds.find(x=>x.id===m.id),v)}else{const o=s.owners.find(o=>o.id===v.owner),t=s.types.find(t=>t.id===v.type);if(!o||!t)throw Error('Selecciona propietario y tipo.');s.molds.push({id:Model.uid(),...v,code:Model.nextCode(s,o,t),location:'',destination:'',status:'Pendiente de ubicar'})}}));
}
function movement(id){if(!state.molds.length){toast('Registra primero un molde.');return}modal('Registrar movimiento',select('Molde','mold',state.molds.map(m=>({id:m.id,name:m.code+' · '+(m.name||'Sin referencia')+' · '+(m.location||m.status)})),id)+select('Movimiento','kind',['Entrada','Salida','Traslado'].map(x=>({id:x,name:x})),'Entrada')+`<div id="location-fields">${select('Ubicación de destino','location',state.locations.map(l=>({id:l.code,name:l.code})))}</div><div id="exit-fields" hidden>${label('Destino de la salida','destination','text','','maxlength="150"')}${select('Estado al salir','status',['En producción','En mantenimiento','Fuera del almacén'].map(x=>({id:x,name:x})),'En producción',false)}</div>`+label('Persona responsable','person','text','','required maxlength="100"')+notes()+'<p class="hint">La fecha y la hora se registran automáticamente. El historial conserva el origen y el destino.</p>',v=>mutate(s=>Model.move(s,v)));
 $('f-kind').onchange=()=>{const exit=$('f-kind').value==='Salida';$('location-fields').hidden=exit;$('f-location').required=!exit;$('exit-fields').hidden=!exit;$('f-destination').required=exit;$('f-status').required=exit};
}
function movementsTable(rows){return table(['Fecha','Molde','Movimiento','Origen','Destino','Responsable','Notas'],rows.map(v=>`<tr><td>${esc(new Date(v.at).toLocaleString('es-ES'))}</td><td class="code">${esc(v.code)}</td><td>${esc(v.kind)}</td><td>${esc(v.from)}</td><td>${esc(v.to)}</td><td>${esc(v.person)}</td><td>${esc(v.notes)}</td></tr>`))}
function labelHtml(kind){return (kind==='molds'?state.molds:state.locations).map(x=>`<div class="label"><small>ROTOFORMAS · ${kind==='molds'?'MOLDE':'UBICACIÓN'}</small><strong class="code">${esc(x.code)}</strong>${kind==='molds'?`<div>${esc(ownerName(x))} · ${esc(typeName(x))}</div><div>${esc(x.name||'Referencia pendiente')}</div>`:`<div>Estantería ${x.e} · Módulo ${x.m} · Nivel ${x.n}</div>`}</div>`).join('')}
function render(){
 $('nav').innerHTML=pages.map(p=>`<button data-page="${p}" class="${p===page?'active':''}">${p}</button>`).join('');$('title').textContent=page==='Inicio'?'Vista general':page;
 const c=$('content');
 if(page==='Inicio'){const stored=state.molds.filter(m=>m.location).length,occupied=new Set(state.molds.filter(m=>m.location).map(m=>m.location)).size;c.innerHTML=`<div class="cards">${[['Moldes registrados',state.molds.length],['En el almacén',stored],['Ubicaciones',state.locations.length],['Ubicaciones ocupadas',occupied]].map(([n,v])=>`<div class="card"><div class="muted">${n}</div><div class="number">${v}</div></div>`).join('')}</div><section class="panel"><div class="toolbar"><h2>Prepara tu almacén</h2><span class="tag">${state.molds.length?'Inventario en marcha':'Inventario vacío'}</span></div><div class="steps"><div class="step"><h3>Define los catálogos</h3><p class="muted">Propietarios y tipos con sus abreviaturas.</p><button data-page="Catálogos">Configurar catálogos</button></div><div class="step"><h3>Crea las ubicaciones</h3><p class="muted">Estanterías, módulos y niveles a tu medida.</p><button data-action="location">Crear ubicaciones</button></div><div class="step"><h3>Registra los moldes</h3><p class="muted">Completa sus parámetros cuando los tengas.</p><button class="primary" data-action="mold">Registrar molde</button></div></div></section><section class="panel"><div class="toolbar"><h2>Últimos movimientos</h2><button data-action="move">Registrar movimiento</button></div>${state.moves.length?movementsTable(state.moves.slice(-5).reverse()):empty('Todavía no hay movimientos','Las entradas, salidas y cambios de ubicación aparecerán aquí.')}</section>`;}
 if(page==='Moldes'){const molds=state.molds.filter(m=>[m.code,m.name,ownerName(m),typeName(m),m.location,m.status].join(' ').toLowerCase().includes(query.toLowerCase()));c.innerHTML=`<section class="panel"><div class="toolbar"><h2>Inventario de moldes</h2><input id="search" aria-label="Buscar moldes" placeholder="Buscar código, propietario, ubicación…" value="${esc(query)}"><button data-action="csv">Exportar CSV</button><button class="primary" data-action="mold">Registrar molde</button></div>${state.molds.length?table(['Código / referencia','Propietario / tipo','Ubicación / destino','Estado','Ficha'],molds.map(m=>`<tr><td><b class="code">${esc(m.code)}</b><div class="chip">${esc(m.name||'Referencia pendiente')}</div></td><td>${esc(ownerName(m))}<div class="chip">${esc(typeName(m))}</div></td><td>${esc(m.location||m.destination||'Pendiente de ubicar')}</td><td><span class="tag">${esc(m.status)}</span></td><td><div class="actions"><button data-edit="${esc(m.id)}">Ver / editar</button><button data-move="${esc(m.id)}">Mover</button></div></td></tr>`))+(molds.length?'':'<p>No se encontraron moldes.</p>'):empty('Tu inventario empieza aquí','Añade primero propietarios y tipos. Puedes dejar los parámetros técnicos para más adelante.','Registrar primer molde','mold')}</section>`;}
 if(page==='Ubicaciones'){c.innerHTML=`<section class="panel"><div class="toolbar"><h2>Mapa de ubicaciones</h2><button class="primary" data-action="location">Crear ubicaciones</button></div><p class="muted">E = Estantería · M = Módulo · N = Nivel. Los niveles se cuentan desde abajo. Una ubicación puede contener varios moldes.</p>${!state.locations.length?empty('Configura la distribución del almacén','Indica el número de estantería, sus módulos y sus niveles.','Crear ubicaciones','location'):'<div class="rack-map">'+[...new Set(state.locations.map(l=>l.e))].sort((a,b)=>b-a).map(e=>`<div class="rack"><h3>Estantería E${e}</h3>${[...new Set(state.locations.filter(l=>l.e===e).map(l=>l.m))].map(m=>`<div class="muted">Módulo M${m}</div><div class="levels">${state.locations.filter(l=>l.e===e&&l.m===m).sort((a,b)=>b.n-a.n).map(l=>{const molds=state.molds.filter(m=>m.location===l.code);return `<div class="level"><b class="code">${l.code}</b><div class="chip">${molds.length?molds.map(m=>esc(m.code)).join('<br>'):'Sin moldes'}</div></div>`}).join('')}</div>`).join('')}</div>`).join('')+'</div>'}</section>`;}
 if(page==='Movimientos')c.innerHTML=`<section class="panel"><div class="toolbar"><h2>Historial de movimientos</h2><button class="primary" data-action="move">Registrar movimiento</button></div><p class="muted">Cada movimiento conserva la fecha, el molde, el origen, el destino y la persona responsable.</p>${state.moves.length?movementsTable([...state.moves].reverse()):empty('El historial está vacío','Registra una entrada para situar un molde en el almacén. Después podrás registrar salidas y traslados.','Registrar movimiento','move')}</section>`;
 if(page==='Catálogos')c.innerHTML=`<section class="panel"><div class="toolbar"><h2>Propietarios</h2><button class="primary" data-action="owner">Añadir propietario</button></div>${state.owners.length?table(['Nombre','Abreviatura'],state.owners.map(x=>`<tr><td>${esc(x.name)}</td><td class="code">${esc(x.abbr)}</td></tr>`)):empty('¿De quién es cada molde?','Añade el nombre del propietario y una abreviatura única, por ejemplo ACM.')}</section><section class="panel"><div class="toolbar"><h2>Tipos de molde</h2><button class="primary" data-action="type">Añadir tipo</button></div>${state.types.length?table(['Tipo','Abreviatura'],state.types.map(x=>`<tr><td>${esc(x.name)}</td><td class="code">${esc(x.abbr)}</td></tr>`)):empty('Clasifica los moldes','Define los tipos que utilizáis, por ejemplo depósito (DEP) o tapa (TAP).')}</section><p class="hint">Las abreviaturas se mantienen para conservar los códigos asignados. ACM-DEP-001 es un ejemplo; no se ha creado ningún registro de prueba.</p>`;
 if(page==='Etiquetas')c.innerHTML=`<section class="panel"><div class="toolbar"><h2>Etiquetas para imprimir</h2><select id="label-kind" aria-label="Tipo de etiqueta" style="width:auto"><option value="molds">Moldes</option><option value="locations">Ubicaciones</option></select><button class="primary" data-action="print">Imprimir etiquetas</button></div><p class="muted">Etiquetas de texto para recortar. Selecciona moldes o ubicaciones y utiliza la impresión del navegador.</p><div class="labels" id="label-preview">${labelHtml('molds')}</div><p id="label-empty" class="muted">${state.molds.length?'':'Todavía no hay moldes registrados.'}</p></section>`;
 if(page==='Copias y ayuda')c.innerHTML=`<section class="panel"><h2>Conserva tus datos</h2><p>Esta primera versión guarda el inventario únicamente en el navegador y dispositivo actuales. No tiene sincronización entre equipos. Evita usar una ventana privada para el inventario.</p><div class="toolbar"><button class="primary" data-action="backup">Exportar copia completa</button><label class="file-button">Importar copia<input id="restore" type="file" accept="application/json,.json"></label></div><p class="warning">Importar una copia sustituye el inventario actual en este navegador. Antes de hacerlo, exporta una copia de seguridad.</p><p class="hint">La copia JSON incluye catálogos, ubicaciones, fichas y movimientos. El CSV de moldes sirve para consultar los datos en una hoja de cálculo.</p></section><section class="panel"><h2>Cómo empezar</h2><ol><li><p>Añade propietarios y tipos en Catálogos.</p></li><li><p>Crea las ubicaciones: estantería, módulos y niveles.</p></li><li><p>Registra cada molde. Se le asignará un código único.</p></li><li><p>Registra una entrada para asignarle su ubicación inicial.</p></li><li><p>Imprime las etiquetas y completa los parámetros técnicos cuando los tengas.</p></li></ol><p>Los parámetros pendientes se dejan vacíos. Las medidas se registran en milímetros y el peso en kilogramos. No hay datos de demostración.</p><p>Para corregir un movimiento, registra otro que devuelva el molde a su ubicación correcta y explica el motivo en observaciones.</p></section>`;
 bind();
}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function backup(){download('almacen-moldes-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(state,null,2),'application/json')}
function csv(){const fields=['Código','Propietario','Tipo','Referencia','Estado','Ubicación','Destino','Largo mm','Ancho mm','Alto mm','Peso kg','Material','Piezas','Observaciones'];const rows=state.molds.map(m=>[m.code,ownerName(m),typeName(m),m.name,m.status,m.location,m.destination,m.length,m.width,m.height,m.weight,m.material,m.pieces,m.notes]);const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('moldes.csv','\ufeff'+[fields,...rows].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
const actions={owner:()=>cat('owners'),type:()=>cat('types'),location:newLocations,mold:()=>moldForm(),move:()=>movement(),backup,csv,print:()=>{const kind=$('label-kind').value;if(!state[kind].length){toast('No hay etiquetas que imprimir.');return}$('print-area').innerHTML=`<div class="labels">${labelHtml(kind)}</div>`;window.print()}};
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;query='';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>actions[b.dataset.action]());document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>moldForm(b.dataset.edit));document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>movement(b.dataset.move));if($('search'))$('search').oninput=e=>{const pos=e.target.selectionStart;query=e.target.value;render();$('search').focus();$('search').setSelectionRange(pos,pos)};if($('label-kind'))$('label-kind').onchange=e=>{$('label-preview').innerHTML=labelHtml(e.target.value);$('label-empty').textContent=state[e.target.value].length?'':'Todavía no hay registros de este tipo.'};if($('restore'))$('restore').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('La copia supera los 10 MB.');const next=Model.validate(JSON.parse(await file.text()));if(confirm(`Se sustituirán los datos actuales por ${next.molds.length} moldes, ${next.locations.length} ubicaciones y ${next.moves.length} movimientos. ¿Continuar?`)){persist(next);toast('Copia importada correctamente')}}catch(err){alert('No se importó la copia: '+err.message)}};}
$('backup').onclick=backup;render();
